def word_frequency(text: str) -> dict[str, int]:
    freq = {}
    if not text:
        return freq
    punct = '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~'
    for word in text.lower().split():
        stripped = word.strip(punct)
        if stripped:
            freq[stripped] = freq.get(stripped, 0) + 1
    return freq
